/**
 * @name Command injection in CLI tool
 * @description Command injection via subprocess or os.system calls
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find calls to os.system, subprocess.call, subprocess.Popen, etc.
    exists(API::CallNode call |
      // os.system
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
      or
      // subprocess.call
      call = API::moduleImport("subprocess").getMember("call").getACall() and
      sink = call.getArg(0)
      or
      // subprocess.Popen
      call = API::moduleImport("subprocess").getMember("Popen").getACall() and
      sink = call.getArg(0)
      or
      // subprocess.run
      call = API::moduleImport("subprocess").getMember("run").getACall() and
      sink = call.getArg(0)
      or
      // subprocess.check_output
      call = API::moduleImport("subprocess").getMember("check_output").getACall() and
      sink = call.getArg(0)
      or
      // subprocess.check_call
      call = API::moduleImport("subprocess").getMember("check_call").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Dynamic attribute injection
 * @description User input flowing to dynamic attribute access could lead to attribute injection
 * @kind path-problem
 * @problem.severity high
 * @id py/attribute-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module AttributeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for dynamic attribute access functions
    exists(API::CallNode call |
      // getattr()
      call = API::builtin("getattr").getACall() and
      sink = call.getArg(1)  // The attribute name argument
      or
      // setattr()
      call = API::builtin("setattr").getACall() and
      sink = call.getArg(1)  // The attribute name argument
      or
      // hasattr()
      call = API::builtin("hasattr").getACall() and
      sink = call.getArg(1)  // The attribute name argument
      or
      // delattr()
      call = API::builtin("delattr").getACall() and
      sink = call.getArg(1)  // The attribute name argument
    )
  }
}

module AttributeInjectionFlow = TaintTracking::Global<AttributeInjectionConfig>;
import AttributeInjectionFlow::PathGraph

from AttributeInjectionFlow::PathNode source, AttributeInjectionFlow::PathNode sink
where AttributeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dynamic attribute injection from $@.", source.getNode(), "user input"
